 public function source(string $id):array{
  $f=new Finance($this->db,$this->actor);if(!$f->canWrite())throw new DomainException('Finanzschreibrecht erforderlich.');$e=$f->entry($id);
  if($e['kind']!=='income'||in_array($e['payment_state']??$e['status'],['cancelled','reversed'],true)||!empty($e['reversed_on']))throw new DomainException('Nur aktive Ausgangsrechnungen aus Einnahmen sind unterstützt. Beiträge, Spenden und Ausgaben werden nicht umgedeutet.');
