  foreach($positions as $p){if(!in_array((int)$p['tax_rate'],[0,7,19],true)||$p['gross_cents']<=0)throw new DomainException('Positive Rechnungspositionen mit 0 %, 7 % oder 19 % erfassen.');$sum+=(int)$p['gross_cents'];}
