  $fields=[];foreach(['invoice_number','buyer_reference','seller_name','seller_street','seller_city','seller_postcode','seller_email','seller_contact','seller_phone','seller_tax_number','seller_register','buyer_name','buyer_street','buyer_city','buyer_postcode','buyer_email','delivery_date','iban'] as $key){$value=$input[$key]??null;if(!is_string($value)||!mb_check_encoding($value,'UTF-8')||trim($value)===''||mb_strlen($value)>self::inputLimit($key)||preg_match('/[\x00-\x1f]/',$value))throw new DomainException('Bitte das Feld „'.$labels[$key].'“ ausfüllen bzw. prüfen (höchstens '.self::inputLimit($key).' Zeichen, keine Zeilenumbrüche).');$fields[$key]=trim($value);}
