  $reason=$source['issued']['vat_reason']??($input['vat_reason']??'');if(!is_string($reason)||!mb_check_encoding($reason,'UTF-8')||mb_strlen($reason)>self::inputLimit('vat_reason')||preg_match('/[\x00-\x1f]/',$reason))throw new DomainException('Grund der Steuerbefreiung prüfen.');$fields['vat_reason']=trim($reason);if(in_array(0,array_map('intval',array_column($source['positions'],'tax_rate')),true)&&$fields['vat_reason']==='')throw new DomainException('Für 0 % den tatsächlichen gesetzlichen Grund der Steuerbefreiung angeben.');
  if($source['issued']){foreach(['buyer_name','buyer_street','buyer_city','buyer_postcode','buyer_email','delivery_date'] as $key)if(!($key==='buyer_email'&&($source['issued'][$key]??'')==='')&&$fields[$key]!==$source['issued'][$key])throw new DomainException('XML muss dem ausgegebenen Empfänger- und Leistungsstand entsprechen.');if($fields['invoice_number']!==$source['issued']['number'])throw new DomainException('Die bereits ausgegebene Rechnungsnummer verwenden.');$original=$source['issued']['issuer']??null;if($original){foreach(['name','street','city','postcode','email','phone'] as $field)if($fields['seller_'.$field]!==($original['club'][$field]??''))throw new DomainException('Verkäuferdaten müssen dem ausgegebenen Original entsprechen.');if($fields['seller_tax_number']!==($original['tax']['number']??'')||$fields['iban']!==Iban::normalize($original['bank']['iban']??''))throw new DomainException('Steuernummer und Zahlungskonto müssen dem Original entsprechen.');}}
