  $add($root,'cbc:CustomizationID','urn:cen.eu:en16931:2017#compliant#urn:xeinkauf.de:kosit:xrechnung_3.0');$add($root,'cbc:ProfileID','urn:fdc:peppol.eu:2017:poacc:billing:01:1.0');$add($root,'cbc:ID',$fields['invoice_number']);$add($root,'cbc:IssueDate',$e['document_date']);$add($root,'cbc:DueDate',$e['due_date']);$add($root,'cbc:InvoiceTypeCode','380');$add($root,'cbc:DocumentCurrencyCode','EUR');$add($root,'cbc:BuyerReference',$fields['buyer_reference']);
  foreach(['seller'=>'cac:AccountingSupplierParty','buyer'=>'cac:AccountingCustomerParty'] as $type=>$tag){$party=$add($add($root,$tag),'cac:Party');$add($party,'cbc:EndpointID',$fields[$type.'_email'],['schemeID'=>'EM']);$address=$add($party,'cac:PostalAddress');$add($address,'cbc:StreetName',$fields[$type.'_street']);$add($address,'cbc:CityName',$fields[$type.'_city']);$add($address,'cbc:PostalZone',$fields[$type.'_postcode']);$add($add($address,'cac:Country'),'cbc:IdentificationCode','DE');if($type==='seller'){$tax=$add($party,'cac:PartyTaxScheme');$add($tax,'cbc:CompanyID',$fields['seller_tax_number']);$add($add($tax,'cac:TaxScheme'),'cbc:ID','FC');}$legal=$add($party,'cac:PartyLegalEntity');$add($legal,'cbc:RegistrationName',$fields[$type.'_name']);if($type==='seller')$add($legal,'cbc:CompanyID',$fields['seller_register']);if($type==='seller'){$contact=$add($party,'cac:Contact');$add($contact,'cbc:Name',$fields['seller_contact']);$add($contact,'cbc:Telephone',$fields['seller_phone']);$add($contact,'cbc:ElectronicMail',$fields['seller_email']);}}
  $add($add($root,'cac:Delivery'),'cbc:ActualDeliveryDate',$fields['delivery_date']);$payment=$add($root,'cac:PaymentMeans');$add($payment,'cbc:PaymentMeansCode','58');$add($payment,'cbc:PaymentID',$e['display_number']);$add($add($payment,'cac:PayeeFinancialAccount'),'cbc:ID',$fields['iban']);
  $groups=[];$net=0;$taxSum=0;foreach($source['positions'] as $p){$rate=(int)$p['tax_rate'];$lineNet=(int)$p['gross_cents']-(int)$p['tax_cents'];$groups[$rate]['net']=($groups[$rate]['net']??0)+$lineNet;$groups[$rate]['tax']=($groups[$rate]['tax']??0)+(int)$p['tax_cents'];$net+=$lineNet;$taxSum+=(int)$p['tax_cents'];}
  $tax=$add($root,'cac:TaxTotal');$add($tax,'cbc:TaxAmount',$money($taxSum),['currencyID'=>'EUR']);foreach($groups as $rate=>$group){$sub=$add($tax,'cac:TaxSubtotal');$add($sub,'cbc:TaxableAmount',$money($group['net']),['currencyID'=>'EUR']);$add($sub,'cbc:TaxAmount',$money($group['tax']),['currencyID'=>'EUR']);$cat=$add($sub,'cac:TaxCategory');$add($cat,'cbc:ID',$rate===0?'E':'S');$add($cat,'cbc:Percent',(string)$rate);if($rate===0)$add($cat,'cbc:TaxExemptionReason',$fields['vat_reason']);$add($add($cat,'cac:TaxScheme'),'cbc:ID','VAT');}
