 /** Read the immutable original. Do not turn arbitrary uploaded PDFs into issued invoices. */
 public function hybridSource(string $id,int $version):array{
  require_once __DIR__.'/CiiInvoice.php';$source=$this->source($id);if((int)$source['entry']['version']!==$version)throw new DomainException('Der Beleg wurde geändert. Bitte neu öffnen.');
  $q=$this->db->prepare("SELECT id FROM outgoing_invoices WHERE club_id=? AND entry_id=? AND kind='invoice' AND state='issued'");$q->execute([$source['entry']['club_id'],$id]);$invoiceId=$q->fetchColumn();if(!$invoiceId)throw new DomainException('ZUGFeRD ist nur für hier ausgegebene Originalrechnungen verfügbar. Ältere hochgeladene Rechnungen bleiben unverändert.');
  $invoice=(new OutgoingInvoices($this->db,$this->actor))->get($invoiceId);$documents=new Documents($this->db,$this->actor);$document=$documents->document($invoice['document_id']);$file=$documents->file($invoice['document_id'],1);
  if($document['origin']!=='generated'||$file['mime']!=='application/pdf'||!hash_equals($file['sha256'],hash('sha256',$file['bytes'])))throw new DomainException('Das unveränderte ausgegebene PDF-Original ist nicht verfügbar.');
  $snapshot=json_decode($file['snapshot'],true,512,JSON_THROW_ON_ERROR);
  if(($snapshot['general_invoice']??false)!==true||($snapshot['draft']??true)!==false||($snapshot['payment_reference']??'')!==$invoice['number'])throw new DomainException('PDF-Original und ausgegebene Rechnung passen nicht zusammen.');
  return ['source'=>$source,'invoice'=>$invoice,'original'=>$file,'source_hash'=>CiiInvoice::sourceHash($invoice,$file['sha256'])];
 }
 public function saveHybrid(string $id,int $version,array $confirmation=[]):string{
  $current=$this->hybridSource($id,$version);$snapshot=json_decode($current['original']['snapshot'],true,512,JSON_THROW_ON_ERROR);
  if(isset($snapshot['einvoice'])){(new OutgoingInvoices($this->db,$this->actor))->xml($current['invoice']['id']);return $current['invoice']['document_id'];}
  require_once __DIR__.'/HybridEInvoice.php';$built=$this->hybridSource($id,$version);$built['xml']=CiiInvoice::build($built['invoice'],$confirmation,$built['original']['sha256']);$club=$built['source']['entry']['club_id'];$key=substr(hash('sha256','hybrid|'.$built['invoice']['id'].'|'.$built['original']['sha256'].'|'.$built['xml']),0,32);
  $prior=$this->db->prepare('SELECT document_id FROM document_requests WHERE club_id=? AND request_key=?');$prior->execute([$club,$key]);if($existing=$prior->fetchColumn()){$docs=new Documents($this->db,$this->actor);$current=$docs->document($existing);$file=$docs->file($existing,1);$stored=json_decode($file['snapshot'],true,512,JSON_THROW_ON_ERROR);if((int)$current['revision']!==1||$current['state']!=='active'||!hash_equals((string)($stored['validation']['sha256']??''),hash('sha256',$file['bytes']))||!hash_equals($current['sha256'],$file['sha256'])||($stored['domestic_confirmation']['country']??'')!=='DE'||!hash_equals((string)($stored['domestic_confirmation']['source_hash']??''),$built['source_hash']))throw new DomainException('Das bereits geprüfte ZUGFeRD-Dokument wurde verändert oder archiviert. Bitte das Original prüfen.');return $existing;}
  $result=HybridEInvoice::build($built['original']['bytes'],$built['xml']);$snapshot=['kind'=>'outgoing_hybrid_einvoice','invoice_id'=>$built['invoice']['id'],'invoice_number'=>$built['invoice']['number'],'invoice_version'=>$built['invoice']['version'],'original_document_id'=>$built['invoice']['document_id'],'domestic_confirmation'=>['country'=>'DE','actor'=>$this->actor,'confirmed_at'=>gmdate('c'),'source_hash'=>$built['source_hash'],'evidence'=>'explicit_user_confirmation'],'validation'=>$result['validation']];
  return (new Documents($this->db,$this->actor))->generated('zugferd-'.preg_replace('/[^a-zA-Z0-9_-]/','-',$built['invoice']['number']).'.pdf',$result['bytes'],['title'=>'ZUGFeRD '.$built['invoice']['number'],'kind'=>'invoice','scope'=>'finance','document_date'=>$built['invoice']['data']['document_date'],'links'=>['entry:'.$id]],$key,$snapshot,function()use($id,$version,$built,$confirmation){$now=$this->hybridSource($id,$version);$now['xml']=CiiInvoice::build($now['invoice'],$confirmation,$now['original']['sha256']);if($now!==$built)throw new DomainException('Die Originalrechnung wurde während der Prüfung geändert. Bitte neu öffnen.');});
 }
 public function save(string $id,int $version,array $input):string{
  $built=$this->build($id,$version,$input);$key=substr(hash('sha256',$id.'|'.$version.'|'.$built['xml']),0,32);$prior=$this->db->prepare('SELECT document_id FROM document_requests WHERE club_id=? AND request_key=?');$prior->execute([$built['source']['entry']['club_id'],$key]);if($existing=$prior->fetchColumn()){(new Documents($this->db,$this->actor))->document($existing);return $existing;}$result=EInvoiceValidator::run($built['xml']);if($result['state']!=='valid')throw new DomainException('Die vollständige XRechnungsprüfung wurde nicht bestanden. Bitte Pflichtangaben und die gespeicherten Steuerbeträge prüfen. Es wurde keine XML-Rechnung gespeichert.');
  $snapshot=['kind'=>'outgoing_einvoice','source'=>$built['source'],'fields'=>$built['fields'],'validator'=>$result];$key=substr(hash('sha256',$id.'|'.$version.'|'.$built['xml']),0,32);return (new Documents($this->db,$this->actor))->generated('xrechnung.xml',$built['xml'],['title'=>'XRechnung '.$built['fields']['invoice_number'],'kind'=>'export','scope'=>'finance','document_date'=>$built['source']['entry']['document_date'],'links'=>['entry:'.$id]],$key,$snapshot,function()use($id,$version,$built){$now=$this->source($id);if($now!==$built['source']||(int)$now['entry']['version']!==$version)throw new DomainException('Beleg während der Prüfung geändert. Bitte neu prüfen.');},function(string $document)use($built,$result){$q=$this->db->prepare('INSERT INTO einvoice_validations(club_id,document_id,revision,sha256,actor_id,validator_sha256,configuration_sha256,state,scenario,report,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$built['source']['entry']['club_id'],$document,1,hash('sha256',$built['xml']),$this->actor,$result['validator_sha256'],$result['configuration_sha256'],$result['state'],$result['scenario'],$result['report'],gmdate('c')]);});
 }
